<?php get_header(); while (have_posts()): the_post(); ?><section class="section"><div class="container team-profile"><h1><?php the_title(); ?></h1><?php bl_image(bl_field('photo'), 'profile-photo'); ?><p class="lead"><?php echo bl_text(bl_field('position')); ?></p><p><?php echo bl_text(bl_field('biography')); ?></p><p><?php echo bl_text(bl_field('branch')); ?></p><?php foreach (bl_rows(bl_field('social_links')) as $social): ?><a href="<?php echo esc_url($social['url'] ?? ''); ?>" rel="noopener noreferrer"><?php echo bl_text($social['label'] ?? ''); ?></a><?php endforeach; ?></div></section><?php endwhile; get_footer(); ?>
